#!/bin/zsh
# Cross file generator for iOS device / iOS simulator (arm64, Xcode 27.2 SDKs).
# Usage: gen-cross.sh <macos|ios-device|ios-sim> <outfile> [extra-c-arg ...]
# Extra args (e.g. -DSLIRP_NO_HOST_EXEC) are appended to built-in c_args so
# they survive alongside the -target/-isysroot flags (a command-line -Dc_args
# would REPLACE these, silently losing the deployment target).
set -eu
. "${0:A:h}/env.sh"
plat="$1"; out="$2"; shift 2

case "$plat" in
  macos) sdk=macosx; triple="arm64-apple-macos15.0" ;;
  ios-device) sdk=iphoneos;      triple="arm64-apple-ios$MIN_OS_IOS" ;;
  ios-sim)    sdk=iphonesimulator; triple="arm64-apple-ios$MIN_OS_IOS-simulator" ;;
  *) die "unknown platform $plat" ;;
esac
sdkpath=$(xcrun_sdk_path "$sdk")

system=ios; subsys=ios; needs_wrapper=true
[[ "$plat" == ios-sim ]] && subsys=ios-simulator
if [[ "$plat" == macos ]]; then system=darwin; subsys=macos; needs_wrapper=false; fi

quote_list() {
  local q=""
  for a in "$@"; do q="$q, '$a'"; done
  echo "$q"
}
extra=$(quote_list "$@")

cat > "$out" <<EOF
# Generated by gen-cross.sh — do not edit by hand
[binaries]
c = ['xcrun', '--sdk', '$sdk', 'clang']
cpp = ['xcrun', '--sdk', '$sdk', 'clang++']
objc = ['xcrun', '--sdk', '$sdk', 'clang']
ar = ['xcrun', '--sdk', '$sdk', 'ar']
strip = ['xcrun', '--sdk', '$sdk', 'strip', '-x']
pkgconfig = ['$PKG_CONFIG']
python = ['$PYTHON']

[properties]
needs_exe_wrapper = $needs_wrapper
# pipe2()/dup3() are new in the 27.0 SDKs; force compile-time fallbacks so no
# weak-imported symbols can be NULL on older OS versions (same guard UTM uses).
has_function_pipe2 = false
has_function_dup3 = false

[built-in options]
c_args = ['-target', '$triple', '-isysroot', '$sdkpath'$extra]
cpp_args = ['-target', '$triple', '-isysroot', '$sdkpath'$extra]
objc_args = ['-target', '$triple', '-isysroot', '$sdkpath'$extra]
c_link_args = ['-target', '$triple', '-isysroot', '$sdkpath']
cpp_link_args = ['-target', '$triple', '-isysroot', '$sdkpath']
objc_link_args = ['-target', '$triple', '-isysroot', '$sdkpath']

[host_machine]
system = '$system'
subsystem = '$subsys'
kernel = 'xnu'
cpu_family = 'aarch64'
cpu = 'arm64'
endian = 'little'
EOF
log "wrote cross file $out for $plat (sdk $sdkpath, triple $triple, extra: ${*:-none})"
